import { relationships, type Application } from '../src/lib/enrollment/form.js';

// Column names and code values from supabase/schema/sncs-schema-v12.sql (ERD v12, camelCase).
// Only these fields cross the persistence boundary; processing values are generated by the
// server transaction. gradeLevel is resolved to gradeLevelId inside the transaction.
export function mapEnrollment(data: Application, periodId: string) {
  const optional = (value: string | undefined) => value || null;
  const payment: Record<string, string> = { 'Full Payment/Cash': 'full_cash', Monthly: 'monthly', Quarterly: 'quarterly', 'Semi-Annual': 'semi_annual' };
  return {
    gradeLevel: data.gradeLevel,
    application: {
      periodId, applicantType: data.studentStatus.toLowerCase(),
      strandCode: data.level === 'SHS' ? data.strand : null, paymentMode: payment[data.paymentMode],
      lastName: data.surname, firstName: data.firstName, middleName: optional(data.middleName), suffix: optional(data.suffix),
      birthDate: data.birthday, sex: data.gender.toLowerCase(), birthPlace: data.birthplace, religion: data.religion,
      houseStreet: data.houseStreet, barangay: data.barangay, cityMunicipality: data.cityMunicipality,
      province: data.province, zipCode: optional(data.zipCode),
      primaryContactNumber: data.contact, secondaryContactNumber: optional(data.secondaryContact),
      email: data.email, parentEmail: optional(data.parentEmail),
      lastSchoolName: optional(data.previousSchool), lastSchoolCityMunicipality: optional(data.previousSchoolCity),
      lastSchoolProvince: optional(data.previousSchoolProvince),
    },
    guardians: relationships.filter(relationship => data[`${relationship}LastName`] || data[`${relationship}FirstName`]).map(relationship => ({
      relationship, lastName: data[`${relationship}LastName`], firstName: data[`${relationship}FirstName`],
      middleName: optional(data[`${relationship}MiddleName`]), suffix: optional(data[`${relationship}Suffix`]),
      occupation: optional(data[`${relationship}Occupation`]), contactNumber: optional(data[`${relationship}Contact`]),
      email: optional(data[`${relationship}Email`]), messengerAccount: optional(data[`${relationship}Messenger`]),
    })),
  };
}
